(function(){const API=window.DiagnosticAPI,Q=window.DIAGNOSTIC_QUESTIONS,P=window.PROFILE_QUESTIONS,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));let rows=[],filtered=[];
const optionLabel=(q,id)=>q.options.find(o=>o[0]===id)?.[1]||'Sans réponse';const profileLabel=(q,id)=>q.options.find(o=>o[0]===id)?.[1]||'Non répondu';
async function boot(){if(await API.session())showDashboard();else $('#loginView').classList.remove('hidden')}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();setError('');const b=e.submitter;b.disabled=true;try{await API.signIn($('#teacherEmail').value,$('#teacherPassword').value);showDashboard()}catch(err){setError(err.message==='Invalid login credentials'?'Mot de passe incorrect ou compte non encore créé.':err.message)}finally{b.disabled=false}});
$('#firstAccount').onclick=async()=>{const email=$('#teacherEmail').value.trim(),password=$('#teacherPassword').value;if(!email){setError("Saisissez d'abord votre adresse e-mail.");return}if(password.length<8){setError("Choisissez un mot de passe d'au moins 8 caractères.");return}setError('');try{await API.signUp(email,password);try{await API.signIn(email,password);showDashboard()}catch{setError("Compte créé. Ouvrez l'e-mail de confirmation reçu, puis revenez vous connecter.",'ok')}}catch(err){setError(err.message)}};
function setError(msg,type='error'){$('#loginError').textContent=msg;$('#loginError').className=msg?type:''}
async function showDashboard(){$('#loginView').classList.add('hidden');$('#dashboardView').classList.remove('hidden');await load()}
async function load(){try{rows=await API.list();buildClasses();applyFilters();$('#lastUpdate').textContent=`Dernière actualisation : ${new Date().toLocaleString('fr-FR')}`}catch(e){if(e.message==='Session expirée'){API.signOut();location.reload()}else alert(e.message)}}
function buildClasses(){const current=$('#classFilter').value,classes=[...new Set(rows.map(r=>r.class_name))].sort();$('#classFilter').innerHTML='<option value="">Toutes les classes</option>'+classes.map(c=>`<option${c===current?' selected':''}>${esc(c)}</option>`).join('')}
function applyFilters(){const s=$('#searchInput').value.trim().toLocaleLowerCase('fr'),c=$('#classFilter').value;filtered=rows.filter(r=>(!c||r.class_name===c)&&(!s||r.student_name.toLocaleLowerCase('fr').includes(s)));renderStats();renderTable()}
function renderStats(){const avg=filtered.length?filtered.reduce((a,r)=>a+r.score,0)/filtered.length:0,solid=filtered.filter(r=>r.score>=16).length,support=filtered.filter(r=>r.score<10).length;$('#stats').innerHTML=`<div class="stat"><span>Copies</span><strong>${filtered.length}</strong></div><div class="stat"><span>Moyenne</span><strong>${avg.toFixed(1)}/20</strong></div><div class="stat"><span>Acquis solides</span><strong>${solid}</strong></div><div class="stat"><span>Remédiation prioritaire</span><strong>${support}</strong></div>`}
function renderTable(){$('#emptyState').classList.toggle('hidden',filtered.length>0);$('#reportsBody').innerHTML=filtered.map(r=>{const c=r.domain_scores?.['Connaissances informatiques']?.correct??0,l=r.domain_scores?.['Logique générale']?.correct??0;return `<tr><td><strong>${esc(r.student_name)}</strong></td><td>${esc(r.class_name)} ${esc(r.group_name||'')}</td><td>${new Date(r.created_at).toLocaleDateString('fr-FR')}</td><td>${c*2}/10</td><td>${l*2}/10</td><td><strong>${r.score}/20</strong></td><td><span class="badge ${r.score>=16?'good':r.score<10?'low':''}">${esc(r.level)}</span></td><td><button class="view-btn" data-id="${r.id}">Rapport</button></td></tr>`}).join('');document.querySelectorAll('.view-btn').forEach(b=>b.onclick=()=>openReport(b.dataset.id))}
function openReport(id){const r=rows.find(x=>x.id===id);if(!r)return;$('#reportTitle').textContent=`${r.student_name} · ${r.class_name}${r.group_name?' · '+r.group_name:''}`;const knowledge=r.domain_scores?.['Connaissances informatiques']?.correct??0,logic=r.domain_scores?.['Logique générale']?.correct??0;$('#reportContent').innerHTML=`<div class="report-summary"><div class="mini"><span>Note globale</span><strong>${r.score}/20</strong></div><div class="mini"><span>Connaissances</span><strong>${knowledge*2}/10</strong></div><div class="mini"><span>Logique</span><strong>${logic*2}/10</strong></div><div class="mini"><span>Niveau</span><strong>${esc(r.level)}</strong></div></div><section class="report-section"><h3>Profil numérique</h3><div class="report-profile">${P.map(q=>`<div class="profile-value"><strong>${esc(q.fr)}</strong><br>${esc(profileLabel(q,r.equipment_profile?.[q.id]))}</div>`).join('')}</div></section><section class="report-section"><h3>Réponses de l'élève et réponses attendues</h3>${Q.map((q,i)=>{const given=r.answers?.[q.id],ok=given===q.correct;return `<div class="answer-row ${ok?'ok':'bad'}"><strong>${i+1}. ${esc(q.fr)}</strong><p><span class="answer-label">Réponse de l'élève</span><br>${esc(optionLabel(q,given))}</p><p><span class="answer-label">Réponse attendue</span><br>${esc(optionLabel(q,q.correct))}</p><span class="badge ${ok?'good':'low'}">${ok?'Correcte':'Incorrecte'}</span></div>`}).join('')}</section><section class="observation"><h3>Observation de l'enseignant</h3><textarea id="observationText" maxlength="2000" placeholder="Observation facultative…">${esc(r.teacher_observation)}</textarea><div class="actions"><button class="btn" id="saveObservation">Enregistrer l'observation</button><span class="toast" id="observationState"></span></div></section>`;$('#saveObservation').onclick=async()=>{const b=$('#saveObservation');b.disabled=true;try{const v=$('#observationText').value;await API.updateObservation(r.id,v);r.teacher_observation=v;$('#observationState').textContent='Enregistrée ✓'}catch(e){$('#observationState').textContent=e.message}finally{b.disabled=false}};$('#reportDialog').showModal()}
$('#closeDialog').onclick=()=>$('#reportDialog').close();$('#reportDialog').onclick=e=>{if(e.target===$('#reportDialog'))$('#reportDialog').close()};$('#refreshBtn').onclick=load;$('#logoutBtn').onclick=()=>{API.signOut();location.reload()};$('#searchInput').oninput=applyFilters;$('#classFilter').onchange=applyFilters;
$('#exportBtn').onclick=()=>{const head=['Nom','Classe','Groupe','Date','Connaissances /10','Logique /10','Note /20','Niveau'];const csv=[head,...filtered.map(r=>[r.student_name,r.class_name,r.group_name,new Date(r.created_at).toLocaleString('fr-FR'),(r.domain_scores?.['Connaissances informatiques']?.correct??0)*2,(r.domain_scores?.['Logique générale']?.correct??0)*2,r.score,r.level])].map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`diagnostic-2ac-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)};
boot();
})();
